if (msg.statusCode !== 200 ||
    !Array.isArray(msg.payload) ||
    msg.payload.length === 0) {
    node.error("获取商品数据失败或数据为空", msg);
    return null;
}

const collectedAt = new Date();
const batchId = collectedAt.toISOString();

const products = msg.payload.map(product => ({
    ...product,
    collectedAt,
    batchId
}));

msg.payload = [products];
return msg;

// 下载失败或内容不正确时停止处理
if (Number(msg.statusCode) !== 200 ||
    !Array.isArray(msg.payload) ||
    msg.payload.length === 0) {
    node.error("商品数据获取失败或为空", msg);
    return null;
}

const products = msg.payload;

// 保留官方商家代码，三个人统一使用
const merchants = [
    "AEON", "DCHFOOD", "JASONS",
    "LUNGFUNG", "MANNINGS", "PARKNSHOP",
    "SASA", "WATSONS", "WELLCOME"
];

const collectedAt = new Date();
const batchId = collectedAt.toISOString();

// 优先使用繁体中文，无则使用英文
function displayText(value) {
    if (typeof value === "string") return value;
    if (!value || typeof value !== "object") return "";
    return value["zh-Hant"] || value.en ||
        value["zh-Hans"] || "";
}

const records = [];
const seenProducts = new Set();

for (const product of products) {
    const productCode = String(product.code || "").trim();

    if (!productCode || seenProducts.has(productCode)) {
        node.error("发现缺失或重复的商品编号，停止本批处理", msg);
        return null;
    }
    seenProducts.add(productCode);

    const prices = Array.isArray(product.prices)
        ? product.prices : [];
    const offers = Array.isArray(product.offers)
        ? product.offers : [];

    // 防止来源增加商家后被静默忽略
    for (const entry of [...prices, ...offers]) {
        if (!merchants.includes(entry.supermarketCode)) {
            node.error("出现未知商家代码，请先更新商家清单", msg);
            return null;
        }
    }

    for (const merchantCode of merchants) {
        const quote = prices.find(
            item => item.supermarketCode === merchantCode
        );

        // 无报价使用null，不使用0
        let price = null;
        if (quote && quote.price !== null &&
            quote.price !== undefined &&
            String(quote.price).trim() !== "") {
            const value = Number(quote.price);
            if (Number.isFinite(value) && value > 0) {
                price = value;
            }
        }

        const merchantOffers = offers.filter(
            item => item.supermarketCode === merchantCode
        );

        records.push({
            schemaVersion: 1,
            batchId,
            productCode,
            merchantCode,
            name: displayText(product.name),
            brand: displayText(product.brand),
            category1: displayText(product.cat1Name),
            category2: displayText(product.cat2Name),
            category3: displayText(product.cat3Name),
            nameEn: product.name?.en || "",
            brandEn: product.brand?.en || "",
            category1En: product.cat1Name?.en || "",
            category2En: product.cat2Name?.en || "",
            category3En: product.cat3Name?.en || "",
            offerTextEn: merchantOffers
                .map(item => item.en || "")
                .filter(Boolean)
                .join("\n"),
            price,
            offerText: merchantOffers
                .map(displayText)
                .filter(Boolean)
                .join("\n"),
            // 完整保留各语言优惠原文，便于后续检查
            offersRaw: merchantOffers,
            collectedAt,
            sourceUpdatedAt: null
        });
    }
}

msg.batchSummary = {
    batchId,
    productCount: products.length,
    merchantCount: merchants.length,
    recordCount: records.length,
    quotedRecordCount: records.filter(
        item => item.price !== null
    ).length
};

msg.payload = records;

node.status({
    fill: "green",
    shape: "dot",
    text: `${products.length}款商品 / ${records.length}条记录`
});

return msg;

if (!Array.isArray(msg.payload) || msg.payload.length === 0) {
    node.error("没有可写入的记录", msg);
    return null;
}

// mongodb4的insertMany接收参数数组
msg.payload = [msg.payload];
return msg;

if (flow.get("aCollectionRun")) {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "Collection already running"
    });
    return null;
}

msg.aRunId = msg._msgid;
flow.set("aCollectionRun", msg.aRunId);
// 按香港日期计算今天的起止时间
const now = new Date();
const hkOffset = 8 * 60 * 60 * 1000;
const hkDate = new Date(now.getTime() + hkOffset)
    .toISOString()
    .slice(0, 10);

const start = new Date(hkDate + "T00:00:00+08:00");
const end = new Date(start.getTime() + 24 * 60 * 60 * 1000);

msg.checkDate = hkDate;

// 只查询已确认成功的当天批次
msg.payload = [[
    { $match: { schemaVersion: 1, status: "success", collectedAt: { $gte: start, $lt: end } } },
    { $sort: { collectedAt: -1, _id: -1 } },
    { $limit: 1 }
]];
return msg;

if (!Array.isArray(msg.payload)) {
    node.error("批次查询结果异常，停止采集", msg);
    return null;
}
const batch = msg.payload[0];
if (batch) {
    if (batch.status !== "success" || batch.productCount <= 0 ||
        batch.merchantCount !== 9 || batch.recordCount !== batch.productCount * 9) {
        node.error("成功批次登记内容异常，请检查", msg);
        return null;
    }
    node.status({ fill: "green", shape: "dot", text: "今天已有成功批次，跳过" });
    if (flow.get("aCollectionRun") === msg.aRunId) flow.set("aCollectionRun", null);
    return null;
}
node.status({ fill: "blue", shape: "dot", text: "今天尚无成功批次，开始采集" });
msg.payload = "";
return msg;

if (msg.aRunId &&
    flow.get("aCollectionRun") === msg.aRunId) {
    flow.set("aCollectionRun", null);
}

return msg;

if (msg.aRunId &&
    flow.get("aCollectionRun") === msg.aRunId) {
    flow.set("aCollectionRun", null);
}

return msg;

const productCode = String(msg.payload || "").trim();

if (!productCode) {
    node.error("请输入商品编号", msg);
    return null;
}

// 从最新成功批次读取商品；不存在时返回空数组，不退回旧批次
msg.payload = [[
    { $match: { schemaVersion: 1, status: "success" } },
    { $sort: { collectedAt: -1, _id: -1 } },
    { $limit: 1 },
    {
        $lookup: {
            from: "pricewatch_history",
            let: { selectedBatch: "$_id" },
            pipeline: [
                {
                    $match: {
                        schemaVersion: 1, productCode,
                        $expr: { $eq: ["$batchId", "$$selectedBatch"] }
                    }
                },
                {
                    $project: {
                        _id: 0, productCode: 1, merchantCode: 1,
                        name: 1, nameEn: 1, brand: 1, brandEn: 1,
                        price: 1, offerText: 1, offerTextEn: 1
                    }
                }
            ],
            as: "quotes"
        }
    },
    { $match: { "quotes.0": { $exists: true } } },
    { $project: { _id: 0, batchId: "$_id", collectedAt: 1, quotes: 1 } }
]];
return msg;

const batches = msg.payload;

// 找不到商品时，也输出明确结果
if (!Array.isArray(batches) || batches.length === 0) {
    msg.payload = {
        found: false,
        message: "No product found",
        merchants: []
    };
    return msg;
}

const batch = batches[0];
const quotes = batch.quotes || [];

if (quotes.length === 0) {
    node.error("查询结果没有商家记录", msg);
    return null;
}

// 以分为单位比较，减少小数计算误差
function priceInCents(price) {
    return typeof price === "number" &&
        Number.isFinite(price) && price > 0
        ? Math.round(price * 100)
        : null;
}

// 相同文字只显示一行；英文缺失也不留空行
function bilingual(primary, english) {
    const main = String(primary || "").trim();
    const en = String(english || "").trim();

    return {
        primary: main || en,
        secondary: main && en &&
            main.toLowerCase() !== en.toLowerCase()
            ? en : ""
    };
}

const valid = quotes
    .map(q => priceInCents(q.price))
    .filter(value => value !== null);

const minCents = valid.length ? Math.min(...valid) : null;
const maxCents = valid.length ? Math.max(...valid) : null;

const first = quotes[0];

const merchants = quotes.map(q => {
    const cents = priceInCents(q.price);

    return {
        merchantCode: q.merchantCode,
        price: cents === null ? null : cents / 100,
        available: cents !== null,
        isLowest: cents !== null && cents === minCents,
        differenceFromLowest: cents === null || minCents === null
            ? null : (cents - minCents) / 100,
        offer: bilingual(q.offerText, q.offerTextEn)
    };
});

// 有报价的按价格排序，无报价的放最后
merchants.sort((a, b) => {
    if (a.price === null && b.price === null) {
        return a.merchantCode.localeCompare(b.merchantCode);
    }
    if (a.price === null) return 1;
    if (b.price === null) return -1;
    return a.price - b.price ||
        a.merchantCode.localeCompare(b.merchantCode);
});

msg.payload = {
    found: true,
    productCode: first.productCode,
    name: bilingual(first.name, first.nameEn),
    brand: bilingual(first.brand, first.brandEn),
    batchId: batch.batchId,
    collectedAt: batch.collectedAt,
    currency: "HKD",
    quotedMerchantCount: valid.length,
    lowestPrice: minCents === null ? null : minCents / 100,
    priceSpread: minCents === null
        ? null : (maxCents - minCents) / 100,
    lowestMerchants: merchants
        .filter(m => m.isLowest)
        .map(m => m.merchantCode),
    merchants,
    comparisonBasis: "Unit prices; multi-buy offers excluded"
};

return msg;

