const result = msg.payload;

if (
    !summary ||
    !Number.isInteger(summary.productCount) ||
    summary.productCount <= 0 ||
    summary.merchantCount !== 9 ||
    summary.recordCount !== summary.productCount * 9 ||
    result?.acknowledged !== true ||
    result.insertedCount !== summary.recordCount
) {
    node.error("写入结果与预期不一致，不标记成功批次", msg);
    return null;
}

