    { _id: summary.batchId },
    {
        $setOnInsert: {
            schemaVersion: 1,
            batchId: summary.batchId,
            status: "success",
            collectedAt,
            completedAt: new Date(),
            productCount: summary.productCount,
            merchantCount: summary.merchantCount,
            recordCount: summary.recordCount,
            quotedRecordCount: summary.quotedRecordCount
        }
    },
    { upsert: true }
];

return msg;

const result = msg.payload?.[0];

// 新搜索（第1页）清除之前选择；翻页保留当前比价
if (!result || result.page === 1) {
    return [
        msg,
        { ...msg, payload: null },
        { ...msg, payload: "" }
    ];
}

return [msg, null, null];

