if (msg.topic === "pw:load-categories") return [null, msg];
return [msg, null];

// Display-only formatter; original database records are unchanged.
function text(value) {
    return typeof value === "string" ? value.trim() : "";
}
function generic(value) {
    return /^(?:\(\s*(?:每個|每个|每件|每包|each\s*pc|each|per\s*pc)\s*\)|（\s*(?:每個|每个|每件|每包)\s*）)/i.test(text(value));
}
function join(name, brand) {
    name = text(name); brand = text(brand);
    return generic(name) && brand && !name.includes(brand) ? brand + " " + name : name;
}
function format(item) {
    if (!item || typeof item !== "object") return;
    if (typeof item.name === "string") {
        item.name = join(item.name, item.brand);
        item.nameEn = join(item.nameEn, item.brandEn);
    } else if (item.name && typeof item.name === "object") {
        item.name.primary = join(item.name.primary, item.brand?.primary);
        item.name.secondary = join(item.name.secondary, item.brand?.secondary || item.brand?.primary);
    }
}
if (Array.isArray(msg.payload)) {
    for (const report of msg.payload) {
        if (Array.isArray(report?.results)) report.results.forEach(format);
    }
} else {
    format(msg.payload);
}
return msg;

// Display-only formatter; original database records are unchanged.
