return msg;

const input = msg.payload;
const code = typeof input === 'object' && input ? String(input.productCode || '').trim() : '';
const category = code ? '' : String(input?.value ?? input ?? '').trim();
if (!code && !category) return null;
/** @type {any[]} */
const pipeline = [
  { $match: { schemaVersion: 1, status: 'success' } },
  { $sort: { collectedAt: -1, _id: -1 } },
  { $limit: 1 }
];
if (code) {
  pipeline.push({
    $lookup: {
      from: 'pricewatch_history', let: { selectedBatch: '$_id' },
      pipeline: [
        {
          $match: {
            $expr: {
              $and: [
                { $eq: ['$batchId', '$$selectedBatch'] },
                { $eq: ['$productCode', code] }
              ]
            }
          }
        },
        { $limit: 1 },
        { $project: { _id: 0, productCode: 1, name: 1, nameEn: 1, brand: 1, brandEn: 1, category1: 1 } }
      ], as: 'entryProduct'
    }
  });
  pipeline.push({ $set: { selectedCategory: { $ifNull: [{ $arrayElemAt: ['$entryProduct.category1', 0] }, ''] } } });
} else {
  pipeline.push({ $set: { selectedCategory: { $literal: category } } });
}
