    records: 1
  }
});
msg.payload = [pipeline];
return msg;

const row = Array.isArray(msg.payload) ? msg.payload[0] : null;
if (!row) { msg.payload = []; return [msg, null]; }
const rows = row.records || [];
const products = new Map();
const merchants = new Set();
const offers = [];
const clean = value => typeof value === 'string' ? value.trim() : '';
const genericName = value => /^(?:\(\s*(?:每個|每个|每件|每包|each\s*pc|each|per\s*pc)\s*\)|（\s*(?:每個|每个|每件|每包)\s*）)/i.test(clean(value));
const completeName = (name, brand, fallback = '') => {
  name = clean(name);
  brand = clean(brand);
  if (genericName(name) && brand && !name.includes(brand)) return brand + ' ' + name;
  return name || brand || clean(fallback);
};
const normalizeProduct = item => item && typeof item === 'object' ? {
  ...item,
  name: completeName(item.name, item.brand, item.nameEn || item.productCode),
  nameEn: completeName(item.nameEn, item.brandEn, item.name || item.productCode)
} : null;
const label = (zh, en) => en && en.trim() && en.trim().toLowerCase() !== String(zh || '').trim().toLowerCase() ? String(zh || '') + ' / ' + en.trim() : String(zh || en || '');
const parseOffer = r => {
  const text = String(r.offerText || r.offerTextEn || '').trim();
  if (!text) return null;
  const productName = completeName(r.name, r.brand, r.nameEn || r.productCode);
  const base = { merchantCode: r.merchantCode, productCode: r.productCode, productName, productNameEn: completeName(r.nameEn, r.brandEn, productName), category2: r.category2 || '', category3: r.category3 || '', originalUnitPrice: r.price == null ? null : Number(r.price), rule: text, supported: false, buyN: null, offerTotal: null };
  if (base.originalUnitPrice == null || base.originalUnitPrice <= 0) return base;
  let m = text.match(/^(?:buy|买|買)\s*(\d+)\s*(?:件)?\s*(?:save|慳|悭)\s*\$\s*([0-9]+(?:\.[0-9]+)?)\s*$/i);
  if (m) { const n = Number(m[1]), total = base.originalUnitPrice * n - Number(m[2]); if (n > 0 && total > 0) return { ...base, supported: true, buyN: n, offerTotal: Number(total.toFixed(2)) }; }
  m = text.match(/^[买買]\s*(\d+)\s*件\s*(?:共|只需|售)?\s*(?:HKD|HK\$|\$)\s*([0-9]+(?:\.[0-9]+)?)\s*(?:元)?\s*$/i);
  if (!m) m = text.match(/^[买買]\s*(\d+)\s*件\s*(?:共|只需|售)?\s*([0-9]+(?:\.[0-9]+)?)\s*元\s*$/i);
  if (!m) m = text.match(/^(?:buy\s*)?(\d+)\s*(?:at|for)\s*\$\s*([0-9]+(?:\.[0-9]+)?)\s*$/i);
  if (m) { const n = Number(m[1]), total = Number(m[2]); if (n > 0 && total > 0) return { ...base, supported: true, buyN: n, offerTotal: total }; }
  return base;
};
for (const r of rows) {
